import { fileURLToPath } from "node:url"

import { migrate as migratePglite } from "drizzle-orm/pglite/migrator"
import type { PgliteDatabase } from "drizzle-orm/pglite"
import { migrate as migratePostgres } from "drizzle-orm/postgres-js/migrator"
import type { PostgresJsDatabase } from "drizzle-orm/postgres-js"

import type { Database } from "./db"

const migrationsFolder = fileURLToPath(new URL("../drizzle", import.meta.url))

/** Applies the committed migrations in drizzle/ (generated by `npm run db:generate`). */
export async function migrate(database: Database) {
  if (database.kind === "pglite") await migratePglite(database.db as unknown as PgliteDatabase, { migrationsFolder })
  else await migratePostgres(database.db as unknown as PostgresJsDatabase, { migrationsFolder })
}
